// The hand-written PTX of IQ2_XXS's fast multi-token expert kernel (C1138, GGML_CUDA_MTOK_IQ_FAST=2): ptx/mtok-iq2_xxs.ptx,
// generated by ptx/gen_mtok_iq2_xxs.py, is the whole kernel of mmvq-pascal-mtok-iq2_xxs-fast.cu written as PTX for the
// products Qwen3.8-Flash-Next's verify pass makes: the fused gate/up launch with SWIGLU, rows of 2,560 weights (10
// super-blocks, 2 lanes a row), groups of up to 2, 4 or 8 members (three entry points), no shared expert, no biases.
// The build packs it with its compute 6.1 SASS into a fatbin (CMakeLists.txt) that this file loads once per device with
// the driver API and launches on ggml's stream. Every other product of the fast kernel runs its CUDA C version.

#include "mmvq-pascal-mtok-iq.cuh"

#include <cstddef>
#include <mutex>

#if !defined(GGML_USE_HIP) && !defined(GGML_USE_MUSA) && !defined(GGML_CUDA_NO_PTX_KERNELS)

#include <cuda.h>

extern const unsigned char ggml_cuda_ptx_mtok_iq2_xxs[];
extern const size_t        ggml_cuda_ptx_mtok_iq2_xxs_size;

// The byte offsets the PTX reads its parameters at (gen_mtok_iq2_xxs.py, ARGS and FUSION): the structs must not move.
static_assert(sizeof(mtok_iq::args) == 168, "mtok_iq::args: the PTX's parameter is 168 bytes");
static_assert(offsetof(mtok_iq::args, vx) == 0 && offsetof(mtok_iq::args, vy) == 8 && offsetof(mtok_iq::args, ids) == 16 &&
              offsetof(mtok_iq::args, dst) == 24, "mtok_iq::args pointers");
static_assert(offsetof(mtok_iq::args, nrows) == 32 && offsetof(mtok_iq::args, row_bytes) == 36 &&
              offsetof(mtok_iq::args, lpr_log2) == 40 && offsetof(mtok_iq::args, niter) == 44 &&
              offsetof(mtok_iq::args, nrowblocks) == 48 && offsetof(mtok_iq::args, rb) == 52 &&
              offsetof(mtok_iq::args, gcap) == 56 && offsetof(mtok_iq::args, ncols) == 60 &&
              offsetof(mtok_iq::args, nslots) == 64 && offsetof(mtok_iq::args, ids_stride) == 68 &&
              offsetof(mtok_iq::args, nchunk) == 72 && offsetof(mtok_iq::args, act_tok) == 76, "mtok_iq::args ints");
static_assert(offsetof(mtok_iq::args, nchannels_y) == 80 && offsetof(mtok_iq::args, sample_ratio) == 92,
              "mtok_iq::args fastdiv values");
static_assert(offsetof(mtok_iq::args, channel_bytes_x) == 104 && offsetof(mtok_iq::args, sample_bytes_x) == 112 &&
              offsetof(mtok_iq::args, channel_bytes_y) == 120 && offsetof(mtok_iq::args, sample_bytes_y) == 128 &&
              offsetof(mtok_iq::args, col_bytes_y) == 136 && offsetof(mtok_iq::args, stride_channel_dst) == 144 &&
              offsetof(mtok_iq::args, stride_sample_dst) == 152 && offsetof(mtok_iq::args, stride_col_dst) == 160,
              "mtok_iq::args strides");
static_assert(sizeof(ggml_cuda_mm_fusion_args_device) == 80, "fusion args: the PTX's parameter is 80 bytes");
static_assert(offsetof(ggml_cuda_mm_fusion_args_device, gate) == 8, "fusion args: gate");
static_assert(sizeof(ggml_glu_op) == 4 && GGML_GLU_OP_SWIGLU == 2, "fusion args: the PTX computes SWIGLU only");

namespace {

struct ptx_module {
    bool       tried = false;
    CUmodule   mod   = nullptr;
    CUfunction fn[3] = {}; // groups of up to 2, 4, 8 members
};

ptx_module g_mods[GGML_CUDA_MAX_DEVICES];
std::mutex g_mutex;

// the device's module, loaded on first use; nullptr if it could not be (the caller then runs the C version)
const ptx_module * module_for(const int device) {
    std::lock_guard<std::mutex> lock(g_mutex);
    ptx_module & m = g_mods[device];
    if (!m.tried) {
        m.tried = true;
        CUmodule mod = nullptr;
        if (cuModuleLoadData(&mod, ggml_cuda_ptx_mtok_iq2_xxs) != CUDA_SUCCESS) {
            GGML_LOG_WARN("%s: the PTX kernel mtok-iq2_xxs does not load on device %d; GGML_CUDA_MTOK_IQ_FAST=2 runs the CUDA C version\n",
                          __func__, device);
            return nullptr;
        }
        const char * names[3] = { "mtok_iq2xxs_fast_ptx_ntm2", "mtok_iq2xxs_fast_ptx_ntm4", "mtok_iq2xxs_fast_ptx_ntm8" };
        for (int i = 0; i < 3; ++i) {
            if (cuModuleGetFunction(&m.fn[i], mod, names[i]) != CUDA_SUCCESS) {
                GGML_LOG_WARN("%s: no function %s in the PTX kernel mtok-iq2_xxs\n", __func__, names[i]);
                cuModuleUnload(mod);
                return nullptr;
            }
        }
        m.mod = mod;
    }
    return m.mod ? &m : nullptr;
}

} // namespace

// Whether the PTX takes the product (and then launches it): the fused gate/up launch with SWIGLU, 10 super-blocks a
// row, no shared expert, no biases or scales.
bool ggml_cuda_mtok_iq2_xxs_ptx_launch(const mtok_iq::args & p, const ggml_cuda_mm_fusion_args_device & fusion,
                                       const dim3 grid, const int smem, const bool gate, const int ntm,
                                       cudaStream_t stream) {
    if (!gate || fusion.shared_up || fusion.x_bias || fusion.gate_bias || fusion.x_scale || fusion.gate_scale ||
            fusion.glu_op != GGML_GLU_OP_SWIGLU || p.nchunk != 10 || p.niter != 5 || p.lpr_log2 != 1) {
        return false;
    }
    const ptx_module * m = module_for(ggml_cuda_get_device());
    if (m == nullptr) {
        return false;
    }
    CUfunction fn = m->fn[ntm <= 2 ? 0 : ntm <= 4 ? 1 : 2];
    mtok_iq::args                   pp = p;
    ggml_cuda_mm_fusion_args_device ff = fusion;
    void * params[2] = { &pp, &ff };
    CU_CHECK(cuLaunchKernel(fn, grid.x, grid.y, grid.z, WARP_SIZE, MMVQP_MTOK_IQ_NWARPS, 1, (unsigned) smem, (CUstream) stream,
                            params, nullptr));
    return true;
}

#else

bool ggml_cuda_mtok_iq2_xxs_ptx_launch(const mtok_iq::args &, const ggml_cuda_mm_fusion_args_device &, const dim3, const int,
                                       const bool, const int, cudaStream_t) {
    return false;
}

#endif
